import os
import win32com.client
import winreg

def ensure_windows_recent_tracking_enabled():
    try:
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced", 0, winreg.KEY_SET_VALUE | winreg.KEY_QUERY_VALUE)
        try:
            value, _ = winreg.QueryValueEx(key, "Start_TrackDocs")
            if value == 0:
                winreg.SetValueEx(key, "Start_TrackDocs", 0, winreg.REG_DWORD, 1)
        except FileNotFoundError:
            winreg.SetValueEx(key, "Start_TrackDocs", 0, winreg.REG_DWORD, 1)
        winreg.CloseKey(key)
    except Exception as e:
        print(f"Failed to enable Windows recent tracking: {e}")

def get_recent_dir():
    return os.path.join(os.environ.get('APPDATA', ''), r'Microsoft\Windows\Recent')

def list_recent_lnk_files():
    recent_dir = get_recent_dir()
    if not os.path.exists(recent_dir):
        return []

    lnk_files = []
    try:
        for entry in os.scandir(recent_dir):
            if entry.is_file() and entry.name.lower().endswith('.lnk'):
                lnk_files.append((entry.path, entry.stat().st_mtime))
    except Exception:
        pass

    # Sort by modification time descending
    lnk_files.sort(key=lambda x: x[1], reverse=True)
    return [p for p, _ in lnk_files]

def resolve_lnk_target(lnk_path):
    try:
        shell = win32com.client.Dispatch("WScript.Shell")
        shortcut = shell.CreateShortCut(lnk_path)
        target = shortcut.Targetpath
        return target
    except Exception:
        return None

def is_directory_target(target_path):
    return os.path.isdir(target_path)

import os
import json
import time
from PySide6.QtCore import QObject, Signal, QTimer
from core.windows_recent import list_recent_lnk_files, resolve_lnk_target, is_directory_target, ensure_windows_recent_tracking_enabled
from utils.path_helper import get_base_dir

HISTORY_FILE = os.path.join(get_base_dir(), "recent_history.json")

class RecentManager(QObject):
    items_changed = Signal(list)

    def __init__(self, max_items=30, parent=None):
        super().__init__(parent)
        self.max_items = max_items
        self.tracking_enabled = True
        self.excluded_extensions = set()

        ensure_windows_recent_tracking_enabled()

        self.history = self._load_history()

        self.poll_timer = QTimer(self)
        self.poll_timer.timeout.connect(self.tick_scan)
        self.poll_timer.start(2000) # Poll every 2 seconds

        self._last_scan_mtime = {} # path -> mtime

    def set_tracking_enabled(self, enabled):
        was_enabled = self.tracking_enabled
        self.tracking_enabled = enabled
        if enabled and not was_enabled:
            self.tick_scan(silent=True)

    def set_excluded_extensions(self, exts):
        if isinstance(exts, list):
            self.excluded_extensions = {self._normalize_ext(e): True for e in exts if e.strip()}
        else:
            self.excluded_extensions = {self._normalize_ext(k): v for k, v in exts.items() if k.strip()}
        self._purge_excluded()

    def _normalize_ext(self, ext):
        ext = ext.strip().lower()
        if ext and not ext.startswith('.'):
            ext = '.' + ext
        return ext

    def _purge_excluded(self):
        changed = False
        new_history = []
        for item in self.history:
            if not self.excluded_extensions.get(item.get("ext"), False):
                new_history.append(item)
            else:
                changed = True
        if changed:
            self.history = new_history
            self._save_history()
            self.items_changed.emit(self.history)

    def _load_history(self):
        if not os.path.exists(HISTORY_FILE):
            return []
        try:
            with open(HISTORY_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save_history(self):
        try:
            with open(HISTORY_FILE, "w", encoding="utf-8") as f:
                json.dump(self.history, f, ensure_ascii=False, indent=4)
        except Exception:
            pass

    def tick_scan(self, silent=False):
        if not self.tracking_enabled and not silent:
            return

        changed = False

        try:
            lnk_paths = list_recent_lnk_files()
        except Exception:
            lnk_paths = []

        # Take the top N recent shortcuts to process
        for lnk in lnk_paths[:50]:
            try:
                mtime = os.path.getmtime(lnk)
            except Exception:
                continue

            if self._last_scan_mtime.get(lnk) == mtime:
                continue
            self._last_scan_mtime[lnk] = mtime

            if silent:
                continue

            target = resolve_lnk_target(lnk)
            if not target or not os.path.exists(target):
                continue

            if is_directory_target(target):
                continue

            _, ext = os.path.splitext(target)
            ext = self._normalize_ext(ext)

            if self.excluded_extensions.get(ext, False):
                continue

            # Add to history
            name = os.path.basename(target)

            # Deduplicate
            existing_idx = -1
            for i, item in enumerate(self.history):
                if item.get("path") == target:
                    existing_idx = i
                    break

            new_item = {
                "path": target,
                "name": name,
                "ext": ext,
                "is_app": ext == ".exe",
                "last_seen": time.time()
            }

            if existing_idx >= 0:
                self.history.pop(existing_idx)

            self.history.insert(0, new_item)
            changed = True

        if changed:
            if len(self.history) > self.max_items:
                self.history = self.history[:self.max_items]
            self._save_history()
            self.items_changed.emit(self.history)

    def clean_missing_files(self):
        changed = False
        new_history = []
        for item in self.history:
            if os.path.exists(item.get("path", "")):
                new_history.append(item)
            else:
                changed = True

        if changed:
            self.history = new_history
            self._save_history()
            self.items_changed.emit(self.history)

    def clear_history(self):
        if self.history:
            self.history.clear()
            self._save_history()
            self.items_changed.emit(self.history)

    def remove_item(self, item_to_remove):
        path = item_to_remove.get("path") if isinstance(item_to_remove, dict) else str(item_to_remove)
        for i, item in enumerate(self.history):
            if item.get("path") == path:
                self.history.pop(i)
                self._save_history()
                self.items_changed.emit(self.history)
                break

    def set_history(self, new_history):
        self.history = new_history
        self._save_history()
        self.items_changed.emit(self.history)

    def get_items(self):
        self.clean_missing_files()
        return self.history

    def open_item(self, item):
        path = item.get("path") if isinstance(item, dict) else str(item)
        if os.path.exists(path):
            try:
                os.startfile(path)
            except Exception as e:
                print(f"Failed to open {path}: {e}")

    def open_item_location(self, item):
        path = item.get("path") if isinstance(item, dict) else str(item)
        if os.path.exists(path):
            import subprocess
            try:
                subprocess.run(['explorer', '/select,', os.path.normpath(path)])
            except Exception as e:
                print(f"Failed to open location for {path}: {e}")

import keyboard
from PySide6.QtCore import QObject, Signal
from PIL import ImageGrab
from core.screenshot import get_all_visible_rects

class HotkeyManager(QObject):
    action_triggered = Signal(str, object, object)

    def __init__(self, hotkeys=None, parent=None):
        super().__init__(parent)
        self.hotkeys = hotkeys or {} # e.g. {"clipboard": "ctrl+shift+v", "screenshot": "win+shift+s"}
        self._registered_hotkeys = {}
        self.paused = False # map name to actual hotkey string registered

        for name, key in self.hotkeys.items():
            self.register_hotkey(name, key)

    def register_hotkey(self, name, key):
        if not key:
            return False

        try:
            # register with keyboard
            def cb(n=name):
                if getattr(self, 'paused', False):
                    return
                payload_img = None
                payload_rects = None
                if n == "smart_screenshot":
                    try:
                        payload_img = ImageGrab.grab(all_screens=True)
                        payload_rects = get_all_visible_rects()
                    except Exception:
                        pass
                self.action_triggered.emit(n, payload_img, payload_rects)

            keyboard.add_hotkey(key, cb, suppress=False)
            self._registered_hotkeys[name] = key
            self.hotkeys[name] = key
            return True
        except Exception as e:
            print(f"Failed to register hotkey {key} for {name}: {e}")
            return False

    def update_hotkey(self, name, new_key):
        # unregister old
        old_key = self._registered_hotkeys.get(name)
        if old_key:
            try:
                keyboard.remove_hotkey(old_key)
            except Exception:
                pass
            del self._registered_hotkeys[name]

        # register new
        if new_key:
            return self.register_hotkey(name, new_key)
        else:
            self.hotkeys[name] = ""
            return True

    def unregister_hotkey(self, name):
        old_key = self._registered_hotkeys.get(name)
        if old_key:
            try:
                keyboard.remove_hotkey(old_key)
            except Exception:
                pass
            self._registered_hotkeys.pop(name, None)
        self.hotkeys[name] = ""
        return True

import json
import os
import base64
import time
import keyboard
from PySide6.QtCore import QObject, Signal, QTimer, QBuffer, QIODevice
from PySide6.QtGui import QClipboard, QImage, QPixmap
from PySide6.QtWidgets import QApplication

from utils.path_helper import get_base_dir
HISTORY_FILE = os.path.join(get_base_dir(), "history.json")

class ClipboardManager(QObject):
    # Emits when a new valid text is added to the history
    history_changed = Signal(list)

    def __init__(self, max_items=20, parent=None):
        super().__init__(parent)
        self.max_items = max_items
        self.history = self._load_history()
        self._clipboard = QApplication.clipboard()
        self.tracking_enabled = True
        self.record_text = True
        self.record_image = True
        self.picture_save_path = ""
        self.max_images = 20

        # Connect to clipboard data change signal
        self._clipboard.dataChanged.connect(self._on_clipboard_changed)

        # Debounce timer for image clipboard changes
        self._debounce_timer = QTimer(self)
        self._debounce_timer.setSingleShot(True)
        self._debounce_timer.setInterval(200)  # 200ms debounce
        self._debounce_timer.timeout.connect(self._process_clipboard)

        # Flag to prevent reading what we just wrote programmatically
        self.ignore_next = False
        self.last_text = None
        self.last_text_at = 0.0
        self.text_dedupe_window = 1.0

    def _load_history(self):
        if not os.path.exists(HISTORY_FILE):
            return []
        try:
            with open(HISTORY_FILE, "r", encoding="utf-8") as f:
                raw = json.load(f)
                return self._dedupe_history(self._normalize_history(raw))
        except Exception as e:
            print(f"Failed to load history: {e}")
            return []

    def _normalize_text_key(self, text):
        import unicodedata
        import re
        text = text or ""
        # 剥离行首的常见序号和列表符号 (如 "1. ", "(一)", "- ", "* ")
        pattern = r'(?m)^\s*(?:[\(（]?(?:[\d]+|[a-zA-Z]|[一二三四五六七八九十百千万]+)[.\)）\]、](?!\d)\s*|[•·*+\-]\s*)'
        text = re.sub(pattern, '', text)

        text = unicodedata.normalize("NFKC", text)
        return "".join(ch for ch in text if unicodedata.category(ch)[0] not in {"Z", "C"})

    def _dedupe_history(self, history):
        deduped = []
        seen_text = set()
        seen_image = set()
        for item in history:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "text":
                key = self._normalize_text_key(item.get("value", ""))
                if key in seen_text:
                    continue
                seen_text.add(key)
                deduped.append(item)
            elif item.get("type") == "image":
                key = item.get("value", "")
                if key in seen_image:
                    continue
                seen_image.add(key)
                deduped.append(item)
        return deduped

    def _normalize_history(self, raw_history):
        if not isinstance(raw_history, list):
            return []

        normalized = []
        for item in raw_history:
            if isinstance(item, dict) and item.get("type") in {"text", "image"}:
                normalized.append(item)
            elif isinstance(item, str):
                normalized.append({"type": "text", "value": item})
        return normalized

    def _save_history(self):
        try:
            with open(HISTORY_FILE, "w", encoding="utf-8") as f:
                json.dump(self.history, f, ensure_ascii=False, indent=4)
        except Exception as e:
            print(f"Failed to save history: {e}")

    def _on_clipboard_changed(self, mode=QClipboard.Clipboard):
        if mode != QClipboard.Clipboard:
            return

        if not self.tracking_enabled:
            return

        if self.ignore_next:
            self.ignore_next = False
            return

        # Restart the debounce timer. If multiple changes arrive rapidly (like a screenshot),
        # only the last one will trigger the processing.
        self._debounce_timer.start()

    def _process_clipboard(self):
        mime_data = self._clipboard.mimeData()
        if mime_data.hasUrls():
            # Windows Explorer file copy often exposes file URLs and may also
            # include the file path as text. Ignore these payloads entirely so
            # copied files do not pollute the clipboard history.
            return
        if mime_data.hasImage() and self.record_image:
            image = self._clipboard.image()
            if not image.isNull():
                import hashlib
                img_data = image.bits().tobytes()
                img_hash = hashlib.md5(img_data).hexdigest()
                if getattr(self, "last_image_hash", None) == img_hash:
                    return
                self.last_image_hash = img_hash
                self.add_image_item(image)
        elif mime_data.hasText() and self.record_text:
            text = mime_data.text().strip().replace('\r\n', '\n').replace('\r', '\n')
            html = mime_data.html() if mime_data.hasHtml() else None
            if text:
                normalized_text = self._normalize_text_key(text)
                now = time.monotonic()
                if getattr(self, "last_normalized_text", None) == normalized_text and (now - self.last_text_at) < self.text_dedupe_window:
                    return
                self.last_normalized_text = normalized_text
                self.last_text_at = now
                self.add_text_item(text, html)

    def _make_text_item(self, text, html=None):
        item = {"type": "text", "value": text}
        if html:
            item["html"] = html
        return item

    def _make_image_item(self, image):
        if not getattr(self, "picture_save_path", ""):
            from utils.path_helper import get_base_dir
            self.picture_save_path = os.path.join(get_base_dir(), "picture")

        if not os.path.exists(self.picture_save_path):
            os.makedirs(self.picture_save_path, exist_ok=True)

        from datetime import datetime
        filename = datetime.now().strftime("IMG_%Y%m%d_%H%M%S_%f.png")
        filepath = os.path.join(self.picture_save_path, filename)

        image.save(filepath, "PNG")

        self._manage_image_cache()

        return {
            "type": "image",
            "value": filepath,
            "is_path": True
        }

    def _manage_image_cache(self):
        if not getattr(self, "picture_save_path", "") or not os.path.exists(self.picture_save_path):
            return

        files = []
        for f in os.listdir(self.picture_save_path):
            p = os.path.join(self.picture_save_path, f)
            if os.path.isfile(p):
                files.append((p, os.path.getmtime(p)))

        limit = getattr(self, "max_images", 20)
        if len(files) > limit:
            files.sort(key=lambda x: x[1]) # oldest first
            # delete oldest until we reach limit
            for i in range(len(files) - limit):
                try:
                    os.remove(files[i][0])
                except Exception:
                    pass

    def _item_key(self, item):
        if item.get("type") == "image":
            return ("image", item.get("value", ""))

        import re
        val = item.get("value", "")
        normalized_val = re.sub(r'\s+', '', val)
        return ("text", normalized_val)

    def _trim_history(self):
        if len(self.history) > self.max_items:
            self.history = self.history[:self.max_items]

    def add_text_item(self, text, html=None):
        # Remove if it already exists (deduplication)
        key = ("text", self._normalize_text_key(text))
        self.history = [item for item in self.history if self._item_key(item) != key]

        # Add to top (most recent)
        self.history.insert(0, self._make_text_item(text, html))
        self._trim_history()

        self._save_history()
        self.history_changed.emit(self.history)

    def add_image_item(self, image):
        item = self._make_image_item(image)
        key = self._item_key(item)
        self.history = [existing for existing in self.history if self._item_key(existing) != key]
        self.history.insert(0, item)
        self._trim_history()

        # Clean missing files before emitting to prevent showing blank entries
        valid_history = []
        for it in self.history:
            if it.get("type") == "image":
                val = it.get("value", "")
                if it.get("is_path", False) or val.endswith('.png'):
                    if not os.path.exists(val):
                        continue
            valid_history.append(it)
        self.history = valid_history

        self._save_history()
        self.history_changed.emit(self.history)

    def remove_item(self, item_to_remove):
        if isinstance(item_to_remove, str):
            item_to_remove = self._make_text_item(item_to_remove)

        key = self._item_key(item_to_remove)
        for item in list(self.history):
            if self._item_key(item) == key:
                self.history.remove(item)
                break

        self._save_history()
        self.history_changed.emit(self.history)

    def clear_history(self, clear_type="all"):
        if clear_type == "all":
            self.history.clear()
        elif clear_type == "text":
            self.history = [item for item in self.history if item.get("type") != "text"]
        elif clear_type ==
